# Essentia menu theme — original composition, generated by code (CC0 / GPL with the app)
import numpy as np, scipy.io.wavfile as wav, scipy.signal as sig
SR = 44100
BPM = 92
BEAT = 60.0 / BPM
BARS = 16
L = int(round(BARS * 4 * BEAT * SR))

def hz(n):  # MIDI note -> Hz
    return 440.0 * 2 ** ((n - 69) / 12.0)

def env(n, a=0.01, d=0.08, s=0.6, r=0.12):
    t = np.arange(n) / SR
    e = np.ones(n) * s
    ai = int(a * SR); di = int(d * SR); ri = int(r * SR)
    ai = min(ai, n); e[:ai] = np.linspace(0, 1, ai) if ai else e[:ai]
    if di and ai < n:
        k = min(di, n - ai); e[ai:ai + k] = np.linspace(1, s, k)
    if ri and n > ri:
        e[-ri:] *= np.linspace(1, 0, ri)
    return e

def square(f, n, duty=0.25):
    t = np.arange(n) / SR
    ph = (t * f) % 1.0
    return np.where(ph < duty, 1.0, -1.0)

def tri(f, n):
    t = np.arange(n) / SR
    ph = (t * f) % 1.0
    return 4 * np.abs(ph - 0.5) - 1

track = {k: np.zeros(L) for k in ('lead', 'bass', 'arp', 'pad', 'hat')}

def place(name, start_beats, dur_beats, sound):
    s = int(round(start_beats * BEAT * SR))
    n = len(sound)
    end = s + n
    if end <= L:
        track[name][s:end] += sound
    else:  # wrap around: seamless loop
        k = L - s
        track[name][s:] += sound[:k]
        track[name][:n - k] += sound[k:]

# Progression (one chord per bar): Am F C G | Am F C E | F G Em Am | F G C C
A, F, C, G, E, Em = 'Am', 'F', 'C', 'G', 'E', 'Em'
prog = [A, F, C, G, A, F, C, E, F, G, Em, A, F, G, C, C]
chords = {
    'Am': (57, 60, 64), 'F': (53, 57, 60), 'C': (48, 52, 55), 'G': (55, 59, 62),
    'E': (52, 56, 59), 'Em': (52, 55, 59),
}
roots = {'Am': 45, 'F': 41, 'C': 48, 'G': 43, 'E': 40, 'Em': 40}

for bar, ch in enumerate(prog):
    b0 = bar * 4
    # bass: root on 1, fifth on 3, little walk on 4&
    r = roots[ch]
    for beat, note, dur in ((0, r, 1.5), (2, r + 7, 1.0), (3, r + 12, 0.5), (3.5, r + 7, 0.5)):
        n = int(dur * BEAT * SR)
        place('bass', b0 + beat, dur, tri(hz(note), n) * env(n, 0.005, 0.1, 0.7, 0.05) * 0.55)
    # arpeggio in eighths, up and down, soft 12.5% pulse
    notes = list(chords[ch]) + [chords[ch][0] + 12]
    pattern = notes + notes[-2:0:-1]
    for i in range(8):
        nt = pattern[i % len(pattern)] + 12
        n = int(0.5 * BEAT * SR)
        place('arp', b0 + i * 0.5, 0.5, square(hz(nt), n, 0.125) * env(n, 0.003, 0.05, 0.25, 0.04) * 0.18)
    # pad: sustained triad, very soft
    n = int(4 * BEAT * SR)
    pad = sum(tri(hz(x + 12), n) for x in chords[ch]) / 3.0
    place('pad', b0, 4, pad * env(n, 0.4, 0.5, 0.8, 0.6) * 0.12)
    # hats on the off-beats
    for i in range(4):
        n = int(0.12 * SR)
        noise = np.random.default_rng(bar * 10 + i).uniform(-1, 1, n)
        noise = sig.lfilter([1, -1], [1, -0.6], noise)
        place('hat', b0 + i + 0.5, 0.12, noise * np.exp(-np.arange(n) / (0.025 * SR)) * 0.10)

# Melody (beat, MIDI note, length in beats) — 16 bars, an original tune
mel = [
    # bars 1-4: question
    (0, 69, 1), (1, 72, 1), (2, 76, 1.5), (3.5, 74, 0.5),
    (4, 72, 1.5), (5.5, 69, 0.5), (6, 72, 2),
    (8, 67, 1), (9, 72, 1), (10, 76, 1), (11, 79, 1),
    (12, 78, 0.5), (12.5, 79, 0.5), (13, 74, 3),
    # bars 5-8: answer
    (16, 69, 1), (17, 72, 1), (18, 76, 1.5), (19.5, 77, 0.5),
    (20, 76, 1), (21, 74, 1), (22, 72, 2),
    (24, 72, 1), (25, 74, 0.5), (25.5, 76, 0.5), (26, 79, 2),
    (28, 76, 1), (29, 71, 1), (30, 68, 2),
    # bars 9-12: lift
    (32, 69, 0.5), (32.5, 72, 0.5), (33, 77, 1.5), (34.5, 76, 0.5), (35, 74, 1),
    (36, 74, 0.5), (36.5, 76, 0.5), (37, 79, 1.5), (38.5, 77, 0.5), (39, 76, 1),
    (40, 76, 1), (41, 79, 1), (42, 83, 1.5), (43.5, 79, 0.5),
    (44, 81, 2), (46, 76, 2),
    # bars 13-16: home
    (48, 77, 1), (49, 76, 1), (50, 74, 1), (51, 72, 1),
    (52, 74, 1.5), (53.5, 76, 0.5), (54, 79, 2),
    (56, 76, 1), (57, 74, 1), (58, 72, 1.5), (59.5, 71, 0.5),
    (60, 72, 3), (63, 64, 0.5), (63.5, 67, 0.5),
]
for beat, note, dur in mel:
    n = int(dur * BEAT * SR)
    t = np.arange(n) / SR
    vib = 1 + 0.004 * np.sin(2 * np.pi * 5.5 * t) * np.clip((t - 0.25) / 0.2, 0, 1)
    ph = np.cumsum(hz(note) * vib) / SR
    tone = np.where((ph % 1.0) < 0.25, 1.0, -1.0) * 0.6 + np.sin(2 * np.pi * ph) * 0.4
    place('lead', beat, dur, tone * env(n, 0.008, 0.12, 0.55, 0.08) * 0.32)

def lowpass(x, fc):
    b, a = sig.butter(2, fc / (SR / 2))
    return sig.filtfilt(b, a, x)

def echo(x, delay_beats, fb, n=4):
    out = x.copy()
    d = int(delay_beats * BEAT * SR)
    for k in range(1, n + 1):
        out += np.roll(x, d * k) * (fb ** k)
    return out

lead = echo(lowpass(track['lead'], 5200), 0.75, 0.32)
arp = echo(lowpass(track['arp'], 4200), 0.5, 0.25)
bass = lowpass(track['bass'], 1800)
pad = lowpass(track['pad'], 2500)
hat = track['hat']

left = lead * 0.95 + arp * 1.1 + bass + pad + hat * 0.8
right = lead * 0.95 + np.roll(arp, int(0.012 * SR)) * 0.9 + bass + np.roll(pad, int(0.02 * SR)) + hat * 1.1
mix = np.stack([left, right], axis=1)
mix /= np.max(np.abs(mix)) * 1.12
wav.write('theme.wav', SR, (mix * 32767).astype(np.int16))
print('seconds', L / SR)
